  "guideStoryTitle": "Заголовок, отображаемый в списке историй.\nнапр. Брак по контракту с высокомерным герцогом",
  "guideStoryDesc": "Описание, отображаемое под обложкой истории.\nНапишите одно-два предложения, чтобы зацепить читателей.",
  "guideStoryHashtag": "Введите хэштеги, начинающиеся с #, разделённые запятыми или пробелами.\nнапр. #романс #одержимость #фэнтези",
  "guideStoreCover": "Обложка, отображаемая в списке историй.\n\nРекомендуемое соотношение: 2:3 (портрет, напр. 400×600px)\n→ Оптимизировано для вертикального карточного макета\n→ Горизонтальные изображения могут обрезаться сверху/снизу",
  "guideCharName": "Имя персонажа.",
  "guideCharImage": "Фото профиля персонажа (макс. 5).\nПервое изображение используется по умолчанию.\nНажмите  в правом верхнем углу, чтобы удалить.\n\nРекомендуемое соотношение: 1:1 или 3:4\n→ Оптимизировано для круглого обрезания профиля\n→ Рекомендуется кадрировать с лицом по центру",
  "guideCharEmotion": "Устанавливает начальную эмоцию этого персонажа к пользователю (вам).\nПеретащите или нажмите на круг для настройки.\nПоложительные эмоции ближе к +100, отрицательные к -100.",
  "guideCharPersonality": "Подробно опишите личность и манеру речи этого персонажа.",
  "guideCharExample": "Напишите краткий пример ситуации, показывающий манеру речи и личность.",
  "guideCoreKeywords": "Введите ключевые слова (через запятую), активирующие отправку этого Core AI.",
  "guideCoreContent": "Содержимое, отправляемое AI при обнаружении ключевого слова.",
  "guideWorldSetting": "Запишите только неизменный лор для всех глав.\nЭто фиксированный промпт, на который AI всегда ссылается.\n※ Информация, изменяющаяся по главам, идёт в поле Доп. инфо главы.",
  "guideAiGoal": "Запишите цель или направление AI в этой главе.\nнапр. Старается завоевать доверие протагониста, но держит дистанцию, опасаясь разоблачения прошлого.",
  "guideCharGoal": "Цель этого персонажа в этой главе.\nУ каждого персонажа могут быть разные цели, что создаёт более объёмную историю.\nнапр. Сближается с протагонистом, чтобы похитить секретный документ.",
  "guidePrevSummary": "Ключевые события, которые AI должен помнить из предыдущей главы.\nИспользуется AI для понимания непрерывности.\nКратко и сфокусировано на ключевых событиях, изменениях отношений и эмоций.",
  "guideChapterInfo": "Изменения или дополнительная информация, которую AI должен знать в этой главе.\n※ Это поле сбрасывается при смене главы.",
  "guideChapterTrigger": "Условие, запускающее следующую главу.\nДобавьте несколько условий — любое из них может запустить переход.\n\nСочетайте Истощение кэша с условиями эмоции или счётчика разговоров для лучшего удержания памяти.",
  "guideIntro": "Первое содержимое, отображаемое при начале чата.\nНажмите Нарратор / Персонаж / Пользователь, чтобы добавить как пузырь диалога.\nВнутренняя мысль: ##текст## | Действие: **текст**",
  "guideBackground": "Устанавливает фоновое изображение игры.\nДобавьте несколько условий — любое OR условие активирует смену фона.\n\nРекомендуемое соотношение: 9:16 (полный экран портрет, напр. 1080×1920px)\n→ Подходит для полного экрана смартфона\n→ Формат 16:9 может показать чёрные полосы",
